/*
 * CHRISTMAS WITH OPEN COPY SPACE / FULL-SCENE SLIDESHOW / REVISION 3
 * Each scene has a different visual design, palette, background and subjects.
 * 25 seconds, 3 scenes, 4K UHD, 60 fps. The full slide changes via a 0.95 s wipe.
 * Backgrounds are stationary inside each slide. No glow or external assets.
 * Canvas 2D only. Time is in SECONDS. No DOM or animation loop is required.
 * Target and minimum video export bitrate: 100,000,000 bits/second.
 * The renderer/encoder must apply that bitrate; this source only draws frames.
 */
const DURATION = 25;
const FPS = 60;
const WIDTH = 3840;
const HEIGHT = 2160;
const BITRATE = 100000000;

const VECTOR_CARD_TOOLS = (() => {
  const TAU = Math.PI * 2;
  function rounded(ctx, x, y, w, h, r) {
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r); ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function star(ctx, x, y, r, points = 5) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const a = -Math.PI / 2 + i * Math.PI / points, rr = (i & 1) ? r * 0.46 : r;
      const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }
  function flake(ctx, radius, color, line = 1.7) {
    ctx.strokeStyle = color; ctx.lineWidth = line; ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI / 2 + i * TAU / 6, c = Math.cos(a), s = Math.sin(a);
      ctx.moveTo(0, 0); ctx.lineTo(c * radius, s * radius);
      for (const f of [0.46, 0.70, 0.88]) {
        const x = c * radius * f, y = s * radius * f;
        for (const sign of [-1, 1]) {
          const b = a + sign * Math.PI * 2 / 3;
          const branch = radius * (f > 0.8 ? 0.12 : 0.19);
          ctx.moveTo(x, y); ctx.lineTo(x + Math.cos(b) * branch, y + Math.sin(b) * branch);
        }
      }
    }
    ctx.stroke();
  }
  return { TAU, rounded, star, flake };
})();
const FESTIVE_DETAILS = (() => {
  const G = VECTOR_CARD_TOOLS;
  function bow(ctx, x, y, scale, face, edge) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    ctx.fillStyle = face; ctx.strokeStyle = edge; ctx.lineWidth = 1.7;
    ctx.beginPath(); ctx.moveTo(-8, -3);
    ctx.bezierCurveTo(-31, -35, -65, -39, -67, -11);
    ctx.bezierCurveTo(-69, 16, -32, 20, -8, 6); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(8, -3);
    ctx.bezierCurveTo(31, -35, 65, -39, 67, -11);
    ctx.bezierCurveTo(69, 16, 32, 20, 8, 6); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-6, 7); ctx.lineTo(-23, 40);
    ctx.lineTo(-8, 33); ctx.lineTo(2, 43); ctx.lineTo(10, 7); ctx.closePath(); ctx.fill(); ctx.stroke();
    G.rounded(ctx, -11, -10, 22, 22, 5); ctx.fill(); ctx.stroke();
    ctx.restore();
  }
  function icon(ctx, kind, ink, scale = 1) {
    ctx.save(); ctx.scale(scale, scale); ctx.strokeStyle = ink; ctx.fillStyle = ink; ctx.lineWidth = 1.5;
    switch (kind % 6) {
      case 0:
        G.star(ctx, 0, 0, 20); ctx.stroke(); break;
      case 1:
        G.flake(ctx, 19, ink, 1.4); break;
      case 2:
        G.rounded(ctx, -17, -13, 34, 30, 3); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, -13); ctx.lineTo(0, 17);
        ctx.moveTo(-17, -3); ctx.lineTo(17, -3); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, -14);
        ctx.bezierCurveTo(-22, -28, -19, -35, 0, -18);
        ctx.bezierCurveTo(19, -35, 22, -28, 0, -14); ctx.stroke(); break;
      case 3:
        G.star(ctx, 0, 0, 21, 4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, 4, 0, G.TAU); ctx.fill(); break;
      case 4:
        ctx.beginPath(); ctx.moveTo(0, -23); ctx.lineTo(16, 0); ctx.lineTo(0, 23);
        ctx.lineTo(-16, 0); ctx.closePath(); ctx.stroke();
        G.star(ctx, 0, 0, 7, 4); ctx.stroke(); break;
      default:
        ctx.beginPath(); ctx.moveTo(0, -18);
        ctx.bezierCurveTo(-14, -18, -16, -6, -16, 9);
        ctx.lineTo(-21, 15); ctx.quadraticCurveTo(0, 22, 21, 15);
        ctx.lineTo(16, 9); ctx.bezierCurveTo(16, -6, 14, -18, 0, -18); ctx.closePath(); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 23, 3, 0, G.TAU); ctx.fill();
        ctx.beginPath(); ctx.ellipse(0, -23, 3, 4, 0, 0, G.TAU); ctx.stroke();
    }
    ctx.restore();
  }
  function cubic(ctx, curve) {
    ctx.beginPath(); ctx.moveTo(curve[0], curve[1]); ctx.bezierCurveTo(...curve.slice(2));
  }
  function point(c, t) {
    const a = 1 - t;
    return {
      x: a*a*a*c[0] + 3*a*a*t*c[2] + 3*a*t*t*c[4] + t*t*t*c[6],
      y: a*a*a*c[1] + 3*a*a*t*c[3] + 3*a*t*t*c[5] + t*t*t*c[7]
    };
  }
  return { bow, icon, cubic, point };
})();
const BAKING_CARD = (() => {
  const G=VECTOR_CARD_TOOLS;
  const cookies=[
    {x:265,y:365,r:115,kind:0,face:'#c69b6c'},
    {x:610,y:270,r:112,kind:1,face:'#cdae80'},
    {x:635,y:575,r:90,kind:0,face:'#bd8d65'},
    {x:260,y:760,r:102,kind:2,face:'#c8a47b'},
    {x:595,y:875,r:82,kind:1,face:'#be906a'}
  ];
  function silhouette(ctx,q,scale=1) {
    const r=q.r*scale;
    if(q.kind===0){ctx.beginPath();ctx.arc(0,0,r,0,G.TAU);}
    else if(q.kind===1)G.star(ctx,0,0,r);
    else{
      ctx.beginPath();
      for(let i=0;i<6;i++){const a=-Math.PI/2+i*G.TAU/6;const x=Math.cos(a)*r,y=Math.sin(a)*r;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}
      ctx.closePath();
    }
  }
  function cookie(ctx,q,index,phase){
    ctx.save();ctx.translate(q.x,q.y+1.2*Math.sin(phase*2+index*0.8));
    ctx.rotate(0.009*Math.sin(phase*2+index));
    silhouette(ctx,q);ctx.fillStyle=q.face;ctx.fill();ctx.strokeStyle='#ead1ae';ctx.lineWidth=2;ctx.stroke();
    silhouette(ctx,q,q.kind===1?0.70:0.85);ctx.strokeStyle='#f0ddbc';ctx.lineWidth=2.2;ctx.stroke();
    if(index===0||q.kind===2){
      G.flake(ctx,q.r*(q.kind===2?0.53:0.63),'#f3dfbd',1.8);
      if(index===0)for(let i=0;i<6;i++){
        const a=i*G.TAU/6;
        ctx.beginPath();ctx.arc(Math.cos(a)*85,Math.sin(a)*85,2.7,0,G.TAU);ctx.fillStyle='#9b6b50';ctx.fill();
      }
    }else if(q.kind===1){
      G.star(ctx,0,0,q.r*0.27,4);ctx.strokeStyle='#f1d9b7';ctx.lineWidth=1.5;ctx.stroke();
    }else{
      for(let row=0;row<4;row++){
        const y=-36+row*24;ctx.beginPath();
        for(let i=0;i<7;i++){const x=-51+i*17,py=y+(i%2?4:-4);if(i===0)ctx.moveTo(x,py);else ctx.lineTo(x,py);}
        ctx.strokeStyle='#f2dcbc';ctx.lineWidth=2;ctx.stroke();
      }
    }
    ctx.restore();
  }
  function canePath(ctx){
    ctx.beginPath();ctx.moveTo(-16,210);ctx.lineTo(-16,20);
    ctx.bezierCurveTo(-16,-61,98,-61,98,20);
    ctx.quadraticCurveTo(98,36,82,36);ctx.quadraticCurveTo(66,36,66,20);
    ctx.bezierCurveTo(66,-18,16,-18,16,20);ctx.lineTo(16,210);
    ctx.quadraticCurveTo(16,226,0,226);ctx.quadraticCurveTo(-16,226,-16,210);ctx.closePath();
  }
  function foreground(ctx,W,H,phase){
    for(let i=0;i<cookies.length;i++)cookie(ctx,cookies[i],i,phase);
    ctx.save();ctx.translate(469,618);ctx.rotate(-0.04+0.007*Math.sin(phase*2));ctx.translate(-41,-100);
    canePath(ctx);ctx.fillStyle='#f0dfc7';ctx.fill();
    ctx.save();canePath(ctx);ctx.clip();
    ctx.strokeStyle='#b96d70';ctx.lineWidth=9;
    for(let y=-100;y<=280;y+=29){ctx.beginPath();ctx.moveTo(-65,y+40);ctx.lineTo(145,y-40);ctx.stroke();}
    ctx.restore();canePath(ctx);ctx.strokeStyle='#7c514d';ctx.lineWidth=1.8;ctx.stroke();ctx.restore();
  }
  return { foreground };
})();
const RIBBON_CARD = (() => {
  const TAU = Math.PI * 2;
  const colors = {
    outline: '#edc8b3', seam: '#dfa69c', wine: '#a7485b',
    wineDark: '#713043', blush: '#cb7c89', paper: '#e5c7b7',
    ink: '#7a394b', thread: '#d4aa96'
  };
  const clamp = x => Math.max(0, Math.min(1, x));
  const ease = x => { x = clamp(x); return x * x * x * (x * (x * 6 - 15) + 10); };
  const lerp = (a, b, p) => a + (b - a) * p;

  function roundedRect(ctx, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function starPath(ctx, x, y, r, count = 5, rotation = -Math.PI / 2) {
    ctx.beginPath();
    for (let i = 0; i < count * 2; i++) {
      const angle = rotation + i * Math.PI / count;
      const radius = (i & 1) ? r * 0.46 : r;
      const px = x + Math.cos(angle) * radius;
      const py = y + Math.sin(angle) * radius;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function snowflake(ctx, radius, color, lineWidth = 1.55) {
    ctx.strokeStyle = color; ctx.lineWidth = lineWidth;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = i * TAU / 6 - Math.PI / 2;
      const c = Math.cos(a), s = Math.sin(a);
      ctx.moveTo(0, 0); ctx.lineTo(c * radius, s * radius);
      for (const f of [0.52, 0.77]) {
        const x = c * radius * f, y = s * radius * f;
        for (const sign of [-1, 1]) {
          const b = a + Math.PI + sign * Math.PI / 3;
          ctx.moveTo(x, y);
          ctx.lineTo(x + Math.cos(b) * radius * 0.22, y + Math.sin(b) * radius * 0.22);
        }
      }
    }
    ctx.stroke();
  }

  function ribbon(ctx, run, drop) {
    const c = colors;
    const face = ctx.createLinearGradient(60, 50, 350, 200);
    face.addColorStop(0, '#b65d70'); face.addColorStop(1, '#934154');
    ctx.beginPath();
    ctx.moveTo(run, 52); ctx.lineTo(245, 52);
    ctx.bezierCurveTo(146, 52, 72, 118, 72, 215);
    ctx.lineTo(72, drop); ctx.lineTo(89, drop - 16); ctx.lineTo(106, drop);
    ctx.lineTo(106, 215);
    ctx.bezierCurveTo(106, 137, 165, 86, 245, 86);
    ctx.lineTo(run, 86); ctx.lineTo(run - 16, 69); ctx.closePath();
    ctx.fillStyle = face; ctx.fill();
    ctx.strokeStyle = c.outline; ctx.lineWidth = 1.75; ctx.stroke();

    // Parallel inset seams terminate before the notched ribbon ends.
    ctx.strokeStyle = c.seam; ctx.lineWidth = 1.05;
    ctx.beginPath();
    ctx.moveTo(run - 29, 60); ctx.lineTo(245, 60);
    ctx.bezierCurveTo(150, 60, 80, 121, 80, 215);
    ctx.lineTo(80, drop - 23);
    ctx.moveTo(run - 29, 78); ctx.lineTo(245, 78);
    ctx.bezierCurveTo(161, 78, 98, 133, 98, 215);
    ctx.lineTo(98, drop - 23); ctx.stroke();
  }

  function bow(ctx, angle, phase, warm) {
    ctx.save(); ctx.translate(149, 158); ctx.rotate(angle);
    const c = colors;
    // The tails, loops and knot are intentional attached layers of ONE bow.
    ctx.fillStyle = c.wine; ctx.strokeStyle = c.outline; ctx.lineWidth = 1.9;
    ctx.beginPath(); ctx.moveTo(-12, 7);
    ctx.bezierCurveTo(-31, 42, -55, 81, -56, 143);
    ctx.lineTo(-34, 126); ctx.lineTo(-13, 142);
    ctx.bezierCurveTo(-15, 96, 7, 53, 10, 9); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(7, 6);
    ctx.bezierCurveTo(18, 39, 33, 70, 64, 105);
    ctx.lineTo(65, 80); ctx.lineTo(86, 73);
    ctx.bezierCurveTo(55, 53, 37, 29, 21, 4); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.strokeStyle = c.seam; ctx.lineWidth = 1.05;
    ctx.beginPath(); ctx.moveTo(-3, 27); ctx.bezierCurveTo(-20, 64, -35, 89, -37, 114);
    ctx.moveTo(21, 23); ctx.bezierCurveTo(31, 46, 43, 64, 59, 79); ctx.stroke();

    const left = ctx.createLinearGradient(-106, -45, -5, 20);
    left.addColorStop(0, warm ? '#cc8b91' : '#c87585'); left.addColorStop(1, '#a74c60');
    ctx.fillStyle = left; ctx.strokeStyle = c.outline; ctx.lineWidth = 1.9;
    ctx.beginPath(); ctx.moveTo(-11, -5);
    ctx.bezierCurveTo(-45, -53, -107, -65, -108, -20);
    ctx.bezierCurveTo(-109, 24, -51, 26, -11, 8);
    ctx.quadraticCurveTo(-4, 1, -11, -5); ctx.closePath(); ctx.fill(); ctx.stroke();
    const right = ctx.createLinearGradient(8, 18, 108, -45);
    right.addColorStop(0, '#aa4b60'); right.addColorStop(1, warm ? '#d39496' : '#cd8190');
    ctx.fillStyle = right;
    ctx.beginPath(); ctx.moveTo(11, -5);
    ctx.bezierCurveTo(45, -53, 105, -59, 108, -17);
    ctx.bezierCurveTo(110, 23, 49, 25, 11, 8);
    ctx.quadraticCurveTo(4, 1, 11, -5); ctx.closePath(); ctx.fill(); ctx.stroke();

    ctx.strokeStyle = c.seam; ctx.lineWidth = 1.15;
    ctx.beginPath(); ctx.moveTo(-21, 0); ctx.bezierCurveTo(-55, -23, -78, -28, -91, -17);
    ctx.moveTo(21, 0); ctx.bezierCurveTo(55, -21, 80, -27, 91, -14); ctx.stroke();
    roundedRect(ctx, -17, -14, 34, 29, 7);
    ctx.fillStyle = c.wineDark; ctx.fill();
    ctx.strokeStyle = c.outline; ctx.lineWidth = 1.8; ctx.stroke();
    ctx.strokeStyle = c.seam; ctx.lineWidth = 1.05;
    ctx.beginPath(); ctx.moveTo(-8, -7); ctx.lineTo(-8, 8);
    ctx.moveTo(8, -7); ctx.lineTo(8, 8); ctx.stroke();
    ctx.restore();
  }

  function tagPath(ctx) {
    ctx.beginPath(); ctx.moveTo(-12, -54); ctx.lineTo(12, -54);
    ctx.lineTo(36, -29); ctx.lineTo(36, 43);
    ctx.quadraticCurveTo(36, 51, 28, 51); ctx.lineTo(-28, 51);
    ctx.quadraticCurveTo(-36, 51, -36, 43); ctx.lineTo(-36, -29); ctx.closePath();
  }

  function tagMotif(ctx, mode, ink) {
    ctx.strokeStyle = ink; ctx.fillStyle = ink; ctx.lineWidth = 1.3;
    ctx.save(); ctx.translate(0, 8);
    if (mode === 0) {
      starPath(ctx, 0, -3, 17); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-17, 26); ctx.lineTo(17, 26); ctx.stroke();
      ctx.beginPath(); ctx.arc(0, 17, 1.7, 0, TAU); ctx.fill();
    } else if (mode === 1) {
      snowflake(ctx, 20, ink, 1.35);
      ctx.beginPath(); ctx.moveTo(-11, 28); ctx.lineTo(11, 28); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.moveTo(0, -23); ctx.lineTo(19, 0);
      ctx.lineTo(0, 23); ctx.lineTo(-19, 0); ctx.closePath(); ctx.stroke();
      starPath(ctx, 0, 0, 9, 4); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-9, 31); ctx.lineTo(9, 31); ctx.stroke();
    }
    ctx.restore();
  }

  function tag(ctx, x, y, tilt, mode, nextMode, wipe, warm) {
    const c = colors;
    const holeX = x + Math.sin(tilt) * 36;
    const holeY = y - Math.cos(tilt) * 36;
    ctx.save(); ctx.translate(x, y); ctx.rotate(tilt);
    tagPath(ctx); ctx.fillStyle = warm ? '#d8b6a4' : c.paper; ctx.fill();
    ctx.strokeStyle = '#f0d9c9'; ctx.lineWidth = 1.8; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, -36, 4, 0, TAU);
    ctx.fillStyle = c.ink; ctx.fill();
    ctx.strokeStyle = '#b27973'; ctx.lineWidth = 1.1; ctx.stroke();
    ctx.strokeStyle = '#b5817c'; ctx.lineWidth = 1;
    roundedRect(ctx, -27, -21, 54, 64, 4); ctx.stroke();
    const split = -24 + wipe * 70;
    ctx.save(); ctx.beginPath(); ctx.rect(-24, split, 48, 46 - split); ctx.clip();
    tagMotif(ctx, mode, c.ink); ctx.restore();
    ctx.save(); ctx.beginPath(); ctx.rect(-24, -24, 48, split + 24); ctx.clip();
    tagMotif(ctx, nextMode, c.ink); ctx.restore();
    ctx.restore();
    // The string is in front of the paper and terminates at its punched hole.
    ctx.strokeStyle = c.thread; ctx.lineWidth = 1.25;
    ctx.beginPath(); ctx.moveTo(164, 168);
    ctx.bezierCurveTo(264, 218, 265, holeY - 53, holeX, holeY); ctx.stroke();
  }

  function pendant(ctx, drop, y, phase, warm) {
    const x = 101 + 3 * Math.sin(phase * 2 + (warm ? 1.4 : 0));
    ctx.strokeStyle = colors.thread; ctx.lineWidth = 1.25;
    ctx.beginPath(); ctx.moveTo(89, drop - 16);
    ctx.bezierCurveTo(90, drop + 47, x, y - 74, x, y - 38); ctx.stroke();
    ctx.save(); ctx.translate(x, y); ctx.rotate(0.035 * Math.sin(phase * 2));
    ctx.beginPath(); ctx.ellipse(0, -33, 5, 7, 0, 0, TAU);
    ctx.strokeStyle = colors.outline; ctx.lineWidth = 1.65; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 29, 0, TAU);
    ctx.fillStyle = warm ? '#a95a69' : '#7f394e'; ctx.fill();
    ctx.strokeStyle = colors.outline; ctx.lineWidth = 1.8; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 23, 0, TAU);
    ctx.strokeStyle = colors.seam; ctx.lineWidth = 1.05; ctx.stroke();
    snowflake(ctx, 16, colors.outline, 1.25);
    ctx.restore();
  }

  function corner(ctx, pose, phase, mode, nextMode, wipe, warm) {
    ribbon(ctx, pose.run, pose.drop);
    tag(ctx, pose.tagX, pose.tagY, pose.tilt + 0.009 * Math.sin(phase * 2 + 0.5), mode, nextMode, wipe, warm);
    pendant(ctx, pose.drop, pose.pendant, phase, warm);
    bow(ctx, pose.bow + 0.007 * Math.sin(phase * 2), phase, warm);
    ctx.save(); ctx.translate(pose.run + 35, 69);
    ctx.rotate(0.07 * Math.sin(phase * 2 + 0.7));
    starPath(ctx, 0, 0, 12.5, 4);
    ctx.fillStyle = '#c89183'; ctx.fill();
    ctx.strokeStyle = colors.outline; ctx.lineWidth = 1.45; ctx.stroke();
    ctx.restore();
  }


  function foreground(ctx, W, H, phase) {
    const pose = { run: 390, drop: 475, tagX: 239, tagY: 402, tilt: -0.045, bow: -0.065, pendant: 695 };
    ctx.save(); ctx.translate(165, 340 + 1.2 * Math.sin(phase * 2));
    ctx.rotate(-0.01); ctx.scale(0.85, 0.85); ctx.translate(-149, -388);
    corner(ctx, pose, phase, 0, 0, 0, false); ctx.restore();
    ctx.save(); ctx.translate(630, 735 + 1.2 * Math.sin(phase * 2 + 0.8));
    ctx.rotate(Math.PI + 0.01); ctx.scale(0.8, 0.8); ctx.translate(-149, -388);
    corner(ctx, { ...pose, tagX: 243, tagY: 417, bow: -0.02 }, phase + Math.PI, 1, 1, 0, true);
    ctx.restore();
  }

  return { foreground };
})();
const STATIONERY_CARD = (() => {
  const G=VECTOR_CARD_TOOLS,F=FESTIVE_DETAILS;
  function paper(ctx,w,h,face='#ecd8c5') {
    G.rounded(ctx,0,0,w,h,7);ctx.fillStyle=face;ctx.fill();
    ctx.strokeStyle='#785165';ctx.lineWidth=1.8;ctx.stroke();
    G.rounded(ctx,8,8,w-16,h-16,4);ctx.strokeStyle='#b08b91';ctx.lineWidth=1.0;ctx.stroke();
  }
  function postagePath(ctx,w,h) {
    function edge(x,y,dx,dy,length) {
      const count=Math.max(1,Math.round(length/14)),pitch=length/count;
      const point=(u,depth)=>ctx.lineTo(x+dx*u-dy*depth,y+dy*u+dx*depth);
      for(let i=0;i<count;i++) {
        point((i+0.25)*pitch,0);point((i+0.38)*pitch,4);
        point((i+0.62)*pitch,4);point((i+0.75)*pitch,0);
      }
      point(length,0);
    }
    ctx.beginPath();ctx.moveTo(0,0);
    edge(0,0,1,0,w);edge(w,0,0,1,h);
    edge(w,h,-1,0,w);edge(0,h,0,-1,h);ctx.closePath();
  }
  function foreground(ctx,W,H,phase) {
    const drift=1.25*Math.sin(phase*2);
    ctx.save();ctx.translate(500,252+Math.sin(phase*2+0.9));ctx.rotate(-0.035+0.003*Math.sin(phase));ctx.translate(-160,-102.5);
    paper(ctx,320,205,'#ead6c1');
