const CHRISTMAS_SLIDESHOW = (() => {
  const TAU = Math.PI * 2;
  const cards = [{ name: 'Pastel Gift Studio', palette: ['#e0c6bc','#ecd9c8','#f3e8d7'], foreground: GIFTS_CARD.foreground },
    { name: 'Holiday Correspondence', palette: ['#ccb8be','#ad8390','#8c6277'], foreground: STATIONERY_CARD.foreground },
    { name: 'Christmas Baking', palette: ['#6c4949','#a87468','#d6af98'], foreground: BAKING_CARD.foreground }];
  const clamp = x => Math.max(0, Math.min(1, x));
  const ease = x => { x = clamp(x); return x * x * x * (x * (x * 6 - 15) + 10); };
  function paint(ctx, W, H, index, phase) {
    const card = cards[index];
    const bg = ctx.createLinearGradient(0, H, W, 0);
    bg.addColorStop(0, card.palette[0]); bg.addColorStop(0.5, card.palette[1]); bg.addColorStop(1, card.palette[2]);
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    ctx.save(); card.foreground(ctx, W, H, phase); ctx.restore();
  }
  function render(ctx, W, H, currentScene, sceneProgress, sceneDuration, phase) {
    paint(ctx, W, H, currentScene, phase);
    const transitionSeconds = 0.95;
    const transitionStart = 1 - transitionSeconds / sceneDuration;
    const amount = ease((sceneProgress - transitionStart) / (1 - transitionStart));
    if (amount > 0) {
      // A full-scene slideshow wipe replaces background AND all foreground.
      // It does not stretch, morph or relocate the outgoing ornaments.
      const edge = W * (1 - amount);
      ctx.save(); ctx.beginPath(); ctx.rect(edge, 0, W - edge, H); ctx.clip();
      paint(ctx, W, H, (currentScene + 1) % 3, phase);
      ctx.restore();
    }
  }
  return { render, TAU };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  if (!ctx || !Number.isFinite(t) || t < 0 || width <= 0 || height <= 0) return;
  const minSide = Math.min(width, height);
  const scale = minSide / 1080;
  const W = width / scale, H = height / scale;
  const phase = CHRISTMAS_SLIDESHOW.TAU * loopT / duration;
  ctx.save(); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)'; ctx.setLineDash([]); ctx.lineDashOffset = 0;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.miterLimit = 2;
  ctx.scale(scale, scale);
  CHRISTMAS_SLIDESHOW.render(ctx, W, H, currentScene, sceneProgress, sceneDuration, phase);
